      const phi1 = u1 - Math.sin(twoPi * u1) / twoPi;
      const w = phi1 - phi0;
      const dw = ((1 - Math.cos(twoPi * u0)) - (1 - Math.cos(twoPi * u1))) / T;
      wx += g.x * w; wz += g.z * w;
      dwx += g.x * dw; dwz += g.z * dw;
    }
  }
  return { wx, wz, dwx, dwz };
}

function forceToAtt(Fx, Fy, Fz, yaw) {
  const FySafe = Math.max(1.5, Fy);
  const F = Math.hypot(Fx, FySafe, Fz);
  const dx = Fx / F, dy = FySafe / F, dz = Fz / F;
  const cy = Math.cos(yaw), sy = Math.sin(yaw);
  const bx = dx * cy - dz * sy;
  const bz = dx * sy + dz * cy;
  const roll = clamp(-Math.asin(clamp(bz, -0.95, 0.95)), -0.59, 0.59);
  const pitch = clamp(Math.atan2(bx, dy), -0.59, 0.59);
  return { F, roll, pitch };
}

let pass = 0, fails = [];
for (let s = 1; s <= 200; s++) {
  const parameters = trialParameters(s), state = initialState(parameters);
  const simState = initialState(parameters);
  const traj = buildTrajectory(simState.pos);
  let intX = 0, intY = 0, intZ = 0;
  for (let step = 0; step < 1500 && !state.reason; step++) {
    const p = state.pos, v = state.vel, att = state.att, rates = state.rates;
    const tLead = state.t + 0.015 + 0.5 * parameters.lag;
    const rx = sampleTrajectoryAxis(traj, "x", tLead);
    // Phase-adjust y/z near gates so x-error does not cause lateral gate error
    const vxRefSafe = Math.max(0.35, rx.v);
    const dtPhase = state.t < 6.3 ? clamp((p.x - rx.p) / vxRefSafe, -0.18, 0.18) : 0;
    const ry = sampleTrajectoryAxis(traj, "y", tLead + dtPhase);
    const rz = sampleTrajectoryAxis(traj, "z", tLead + dtPhase);

    if (state.t > traj.endTime - 0.4) {
      if (Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > 0.24) {
        ry.p = Math.max(ry.p, 0.12);
      }
    }

    const kpX = 11.0, kdX = 6.2;
    const kpY = 14.0, kdY = 7.2;
    const kpZ = 14.0, kdZ = 7.2;

    const ex = rx.p - p.x, vxErr = rx.v - v.x;
    const ey = ry.p - p.y, vyErr = ry.v - v.y;
    const ez = rz.p - p.z, vzErr = rz.v - v.z;

    intX = clamp(intX + ex * 0.01, -0.15, 0.15);
    intY = clamp(intY + ey * 0.01, -0.15, 0.15);
    intZ = clamp(intZ + ez * 0.01, -0.15, 0.15);

    const axDes = rx.a + kpX * ex + kdX * vxErr + 2.0 * intX;
    const ayDes = ry.a + kpY * ey + kdY * vyErr + 2.5 * intY;
    const azDes = rz.a + kpZ * ez + kdZ * vzErr + 2.5 * intZ;

    const jxDes = rx.j + kpX * vxErr;
    const jyDes = ry.j + kpY * vyErr;
    const jzDes = rz.j + kpZ * vzErr;

    const mass = parameters.mass;
    const windInfo = getWindLookahead(parameters, state.t);

    const Fx = mass * axDes - TASK.linearDrag * (windInfo.wx - v.x);
    const Fy = mass * (ayDes + TASK.gravity) + TASK.linearDrag * v.y;
    const Fz = mass * azDes - TASK.linearDrag * (windInfo.wz - v.z);

    const dFx = mass * jxDes - TASK.linearDrag * (windInfo.dwx - axDes);
    const dFy = mass * jyDes + TASK.linearDrag * ayDes;
    const dFz = mass * jzDes - TASK.linearDrag * (windInfo.dwz - azDes);

    // Choose desired yaw to share large lateral forces across roll and pitch when needed
    let yawDes = 0;
    if (state.t < traj.endTime - 0.3) {
      const horizRatio = Math.hypot(Fx, Fz) / Math.max(4.0, Fy);
      if (horizRatio > 0.45) {
        // Rotate yaw toward 45 deg diagonal of force vector so both roll and pitch share the load
        const forceAngle = Math.atan2(-Fz, Fx);
        const diagAngle = forceAngle >= 0 ? Math.PI / 4 : -Math.PI / 4;
        const rawYaw = clamp(forceAngle - diagAngle, -0.65, 0.65);
        const blend = clamp((horizRatio - 0.45) / 0.15, 0, 1);
        yawDes = blend * rawYaw;
      }
    }

    const eps = 1e-4;
    const att0 = forceToAtt(Fx, Fy, Fz, att.yaw);
    const attP = forceToAtt(Fx + eps * dFx, Fy + eps * dFy, Fz + eps * dFz, att.yaw);
    const attM = forceToAtt(Fx - eps * dFx, Fy - eps * dFy, Fz - eps * dFz, att.yaw);

    const rollRateDes = clamp((attP.roll - attM.roll) / (2 * eps), -4.5, 4.5);
    const pitchRateDes = clamp((attP.pitch - attM.pitch) / (2 * eps), -4.5, 4.5);
    const dF = clamp((attP.F - attM.F) / (2 * eps), -30, 30);

    const cosTilt = Math.max(0.5, Math.cos(att.roll) * Math.cos(att.pitch));
    const Fdes = clamp(Fy / cosTilt + 0.6 * parameters.lag * dF, 0.5, 15.5);

    const inertia = TASK.inertia * mass / TASK.baseMass;
    const dtSub = 0.005;
    const kpAtt = 95;
    const kdAtt = 17;

    const tauRollDes = inertia * (kpAtt * (att0.roll - att.roll) + kdAtt * (rollRateDes - rates.roll) + 0.4 * rates.roll);
    const tauPitchDes = inertia * (kpAtt * (att0.pitch - att.pitch) + kdAtt * (pitchRateDes - rates.pitch) + 0.4 * rates.pitch);
    const tauYawDes = inertia * (25 * (yawDes - att.yaw) - 8 * rates.yaw + 0.4 * rates.yaw);

    const d = [0, 0, 0, 0];
    for (let i = 0; i < 4; i++) {
      const fi = 0.25 * Fdes +
        tauRollDes * MOTOR_Z[i] / (4 * TASK.arm) -
        tauPitchDes * MOTOR_X[i] / (4 * TASK.arm) +
        tauYawDes * SPIN[i] / (4 * TASK.yawCoefficient);
      const scale = i === parameters.weakMotor ? (1 - parameters.weakness) : 1;
      d[i] = clamp(fi / scale, 0, TASK.maxMotorThrust);
    }

    const thrustCmd = (d[0] + d[1] + d[2] + d[3]) / (4 * TASK.maxMotorThrust);
    const tauRollCmd = TASK.arm * (d[0] * MOTOR_Z[0] + d[1] * MOTOR_Z[1] + d[2] * MOTOR_Z[2] + d[3] * MOTOR_Z[3]);
    const tauPitchCmd = -TASK.arm * (d[0] * MOTOR_X[0] + d[1] * MOTOR_X[1] + d[2] * MOTOR_X[2] + d[3] * MOTOR_X[3]);
    const tauYawCmd = TASK.yawCoefficient * (d[0] * SPIN[0] + d[1] * SPIN[1] + d[2] * SPIN[2] + d[3] * SPIN[3]);

    const denom = 65 + 22 * dtSub;
    const rollCmd = att.roll + (tauRollCmd / inertia + 13 * rates.roll - 22 * state.integral.roll) / denom;
    const pitchCmd = att.pitch + (tauPitchCmd / inertia + 13 * rates.pitch - 22 * state.integral.pitch) / denom;
    const yawRateCmd = rates.yaw + tauYawCmd / (8 * inertia);

    const act = {
      thrust: clamp(thrustCmd, 0, 1),
      roll: clamp(rollCmd, -0.6, 0.6),
      pitch: clamp(pitchCmd, -0.6, 0.6),
      yawRate: clamp(yawRateCmd, -2, 2),
    };
    integrate(state, act, parameters, 0.005);
    if (!state.reason) integrate(state, act, parameters, 0.005);
  }
  if (state.reason === "landed") pass++;
  else fails.push({ s, reason: state.reason || "time limit", gates: state.gateIndex, t: +state.t.toFixed(2) });
}
console.log(`New controller: ${pass}/200 passed. Fails (${fails.length}):`, JSON.stringify(fails));
