  }
  for (let i = 0; i < GATES.length; i++) {
    const gate = GATES[i], x = gate.centre.x;
    if ((old.x < x && state.pos.x >= x) || (old.x > x && state.pos.x <= x)) {
      const fraction = (x - old.x) / (state.pos.x - old.x);
      const y = old.y + fraction * (state.pos.y - old.y), z = old.z + fraction * (state.pos.z - old.z);
      const dy = Math.abs(y - gate.centre.y), dz = Math.abs(z - gate.centre.z);
      const half = TASK.gateOpening / 2, outer = half + TASK.gateFrame;
      const fits = dy + TASK.bodyHeight <= half && dz + TASK.bodyRadius <= half;
      const overlapsFrame = dy <= outer + TASK.bodyHeight && dz <= outer + TASK.bodyRadius && !fits;
      if (overlapsFrame) state.reason = "gate frame collision";
      if (i === state.gateIndex && old.x < x && state.pos.x >= x && fits) state.gateIndex++;
    }
  }
  const error = Math.hypot(state.pos.x - PAD.centre.x, state.pos.z - PAD.centre.z);
  if (state.gateIndex === GATES.length && error <= TASK.landingRadius && state.pos.y <= TASK.bodyHeight + 0.025 &&
      norm(state.vel) < TASK.landingSpeed && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < TASK.landingTilt) state.landedFor += dt;
  else state.landedFor = 0;
  if (state.landedFor >= TASK.landingHold && !state.reason) state.reason = "landed";
}

function buildQuinticAxis(p0, v0, a0, p1, v1, a1, T) {
  const c0 = p0, c1 = v0 * T, c2 = 0.5 * a0 * T * T;
  const dp = p1 - (c0 + c1 + c2), dv = v1 * T - (c1 + 2 * c2), da = a1 * T * T - 2 * c2;
  const c3 = 10 * dp - 4 * dv + 0.5 * da;
  const c4 = -15 * dp + 7 * dv - da;
  const c5 = 6 * dp - 3 * dv + 0.5 * da;
  return { c0, c1, c2, c3, c4, c5, T };
}

function sampleQuinticAxis(seg, tau) {
  if (tau <= 0) return { p: seg.c0, v: seg.c1 / seg.T, a: 2 * seg.c2 / (seg.T * seg.T), j: 0 };
  if (tau >= seg.T) {
    const u = 1, T = seg.T, invT = 1 / T, invT2 = invT * invT;
    const p = seg.c0 + seg.c1 + seg.c2 + seg.c3 + seg.c4 + seg.c5;
    const v = invT * (seg.c1 + 2 * seg.c2 + 3 * seg.c3 + 4 * seg.c4 + 5 * seg.c5);
    const a = invT2 * (2 * seg.c2 + 6 * seg.c3 + 12 * seg.c4 + 20 * seg.c5);
    return { p, v, a, j: 0 };
  }
  const u = tau / seg.T;
  const T = seg.T, invT = 1 / T, invT2 = invT * invT, invT3 = invT2 * invT;
  const p = seg.c0 + u * (seg.c1 + u * (seg.c2 + u * (seg.c3 + u * (seg.c4 + u * seg.c5))));
  const v = invT * (seg.c1 + u * (2 * seg.c2 + u * (3 * seg.c3 + u * (4 * seg.c4 + 5 * seg.c5 * u))));
  const a = invT2 * (2 * seg.c2 + u * (6 * seg.c3 + u * (12 * seg.c4 + 20 * seg.c5 * u)));
  const j = invT3 * (6 * seg.c3 + u * (24 * seg.c4 + 60 * seg.c5 * u));
  return { p, v, a, j };
}

function buildTrajectory(startPos) {
  const times = [0, 2.0, 4.0, 5.9, 8.1];
  const pts = [
    { x: startPos.x, y: startPos.y, z: startPos.z },
    { x: GATES[0].centre.x, y: GATES[0].centre.y, z: GATES[0].centre.z },
    { x: GATES[1].centre.x, y: GATES[1].centre.y, z: GATES[1].centre.z },
    { x: GATES[2].centre.x, y: GATES[2].centre.y, z: GATES[2].centre.z },
    { x: PAD.centre.x, y: 0.084, z: PAD.centre.z },
  ];
  const velsX = [0, 0.65, 0.65, 0.58, 0];
  const velsY = [0, 0.12, 0.0, -0.12, 0];
  const segments = [];
  for (let i = 0; i < 4; i++) {
    const t0 = times[i], t1 = times[i + 1], T = t1 - t0;
    // For z (and y), finish the move preHold seconds before each gate and hold through postHold seconds after!
    const preHoldZ = i < 3 ? 0.28 : 0.0;
    const postHoldZ = i > 0 ? 0.06 : 0.0;
    const tz0 = t0 + postHoldZ, tz1 = t1 - preHoldZ;
    segments.push({
