      }
      if (activeGust || Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > 0.20) {
        ref.p.y = Math.max(ref.p.y, 0.16);
        ref.v.y = Math.max(0, ref.v.y);
        ref.a.y = Math.max(0, ref.a.y);
