    }

    const kpX = 9.0, kdX = 5.4;
    const kpY = 12.0, kdY = 6.5;
    const kpZ = 16.0, kdZ = 8.0;

    const ex = ref.p.x - p.x, vxErr = ref.v.x - v.x;
    const ey = ref.p.y - p.y, vyErr = ref.v.y - v.y;
    const ez = ref.p.z - p.z, vzErr = ref.v.z - v.z;

    const axDes = ref.a.x + kpX * ex + kdX * vxErr;
    const ayDes = ref.a.y + kpY * ey + kdY * vyErr;
    const azDes = ref.a.z + kpZ * ez + kdZ * vzErr;

    const mass = parameters.mass;
    const T = 0.08 + 1.6 * parameters.lag;
    let wx = parameters.baseWind.x, wz = parameters.baseWind.z, dwx = 0, dwz = 0;
    const twoPi = 2 * Math.PI;
    for (let i = 0; i < parameters.gusts.length; i++) {
      const g = parameters.gusts[i];
      const u0 = clamp((g.start - state.t) / T, 0, 1);
      const u1 = clamp((g.start + g.duration - state.t) / T, 0, 1);
      if (u1 > u0) {
        const phi0 = u0 - Math.sin(twoPi * u0) / twoPi;
        const phi1 = u1 - Math.sin(twoPi * u1) / twoPi;
        const w = phi1 - phi0;
        const dw = ((1 - Math.cos(twoPi * u0)) - (1 - Math.cos(twoPi * u1))) / T;
        wx += g.x * w; wz += g.z * w;
        dwx += g.x * dw; dwz += g.z * dw;
      }
    }

    const sumM = state.motors[0] + state.motors[1] + state.motors[2] + state.motors[3];
    const bodyX = Math.sin(att.pitch) * Math.cos(att.roll), bodyZ = -Math.sin(att.roll);
    const dx = Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ;
    const dy = Math.cos(att.pitch) * Math.cos(att.roll);
    const dz = -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ;
    const axCur = (sumM * dx + TASK.linearDrag * (wx - v.x)) / mass;
    const ayCur = (sumM * dy - TASK.linearDrag * v.y) / mass - TASK.gravity;
    const azCur = (sumM * dz + TASK.linearDrag * (wz - v.z)) / mass;

    const jxDes = ref.j.x + kpX * vxErr + kdX * (ref.a.x - axCur);
    const jyDes = ref.j.y + kpY * vyErr + kdY * (ref.a.y - ayCur);
    const jzDes = ref.j.z + kpZ * vzErr + kdZ * (ref.a.z - azCur);

    const Fx = mass * axDes - TASK.linearDrag * (wx - v.x);
    const Fy = mass * (ayDes + TASK.gravity) + TASK.linearDrag * v.y;
    const Fz = mass * azDes - TASK.linearDrag * (wz - v.z);

    const dFx = mass * jxDes - TASK.linearDrag * (dwx - axCur);
    const dFy = mass * jyDes + TASK.linearDrag * ayCur;
    const dFz = mass * jzDes - TASK.linearDrag * (dwz - azCur);

    const forceToAtt = (fx, fy, fz, yaw) => {
      const fySafe = Math.max(1.5, fy);
      const F = Math.hypot(fx, fySafe, fz);
      const ddx = fx / F, ddy = fySafe / F, ddz = fz / F;
      const cy = Math.cos(yaw), sy = Math.sin(yaw);
      const bx = ddx * cy - ddz * sy, bz = ddx * sy + ddz * cy;
      const roll = clamp(-Math.asin(clamp(bz, -0.95, 0.95)), -0.58, 0.58);
      const pitch = clamp(Math.atan2(bx, ddy), -0.58, 0.58);
      return { F, roll, pitch };
    };

    const eps = 1e-4;
    const att0 = forceToAtt(Fx, Fy, Fz, att.yaw);
    const attP = forceToAtt(Fx + eps * dFx, Fy + eps * dFy, Fz + eps * dFz, att.yaw);
    const attM = forceToAtt(Fx - eps * dFx, Fy - eps * dFy, Fz - eps * dFz, att.yaw);

    const rollRateDes = clamp((attP.roll - attM.roll) / (2 * eps), -4.0, 4.0);
    const pitchRateDes = clamp((attP.pitch - attM.pitch) / (2 * eps), -4.0, 4.0);
    const dF = clamp((attP.F - attM.F) / (2 * eps), -30, 30);

    const cosTilt = Math.max(0.5, Math.cos(att.roll) * Math.cos(att.pitch));
    const Fdes = clamp(Fy / cosTilt + 0.5 * parameters.lag * dF, 0.5, 15.5);

    const inertia = TASK.inertia * mass / TASK.baseMass;
    const dtSub = 0.005;
